[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$ProjectPath=[IO.Path]::GetFullPath($ProjectPath);$root=Join-Path $ProjectPath 'Research\Verification\Gate13R_48h_10pct_3Lane\v1'
$receipt=Join-Path $ProjectPath 'Research\Gate13R_48h_10pct_3Lane_v1_External_Failure_Receipt.json';$manifest=Join-Path $ProjectPath 'Research\Gate13R_48h_10pct_3Lane_v1_External_Partial_Output_Manifest.json';$diagnosis=Join-Path $ProjectPath 'Research\Gate13R_48h_10pct_3Lane_v1_Failure_Diagnosis.json'
foreach($path in @($receipt,$manifest,$diagnosis)){if(Test-Path $path){throw "Create-new external evidence exists: $path"}}
if(@(Get-Process Unity -ErrorAction SilentlyContinue).Count){throw 'Unity must be quiescent before sealing failure evidence.'}
$checkpoint=Join-Path $root 'verification-checkpoint.json';$executionReceipt=Join-Path $root 'execution-receipt.json';$log=Join-Path $root 'BlockVerification\positive-wave\lane-01-g13r48verify-core-r01-s1-shared-shared-b001.Unity.log';$ready=Join-Path $root 'BlockVerification\positive-wave\lane-01-g13r48verify-core-r01-s1-shared-shared-b001\method-ready.json';$blockCheckpoint=Join-Path $root 'BlockVerification\positive-wave\lane-01-g13r48verify-core-r01-s1-shared-shared-b001\block-checkpoint.json'
function Hash([string]$path){(Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant()};function Relative([string]$path){$path.Substring($ProjectPath.TrimEnd('\').Length+1).Replace('\','/')}
if((Hash $checkpoint)-ne'218eeab50d60a5dc4ed0ad73129ba68846f5def66fce7ee724935c78a9f9d9b0'-or(Hash $log)-ne'339c8dd09d4f0eefa1378d78b741c66cfe7ce87d677480c2a2073364578158c5'){throw 'Frozen checkpoint/log hash differs from the observed terminal evidence.'}
$checkpointObject=Get-Content -Raw $checkpoint|ConvertFrom-Json;if([string]$checkpointObject.status-ne'failed-no-auto-retry-no-resume'-or[string]$checkpointObject.stage-ne'positive-three-lane-barrier'){throw 'Terminal checkpoint identity differs.'}
$logText=Get-Content -Raw $log;if($logText-notmatch'Access token is unavailable; failed to update'-or$logText-notmatch'Serial number assigned to'-or$logText-match'No valid Unity Editor license found|License is not active \(com\.unity\.editor\.headless\)'){throw 'Unity log does not prove the diagnosed transient-warning/success sequence.'}
$files=@(Get-ChildItem $root -Recurse -File -Force|Sort-Object FullName);$fileRows=@($files|ForEach-Object{[pscustomobject][ordered]@{relativePath=Relative $_.FullName;rawBytes=[long]$_.Length;sha256=Hash $_.FullName}})
$locks=@(1..3|ForEach-Object{$path=('H:\DDM_Final_Project_Gate13R48H\v1\lane-{0:D2}\Temp\UnityLockfile'-f$_);if(Test-Path $path){$item=Get-Item $path;[pscustomobject][ordered]@{lane=$_;absolutePath=$path.Replace('\','/');rawBytes=[long]$item.Length;creationTimeUtc=$item.CreationTimeUtc.ToString('o');lastWriteTimeUtc=$item.LastWriteTimeUtc.ToString('o')}}})
$utf8=New-Object Text.UTF8Encoding($false,$true);function Create([string]$path,$value,[int]$depth=50){$json=($value|ConvertTo-Json -Depth $depth).Replace("`r`n","`n").Replace("`r","`n")+"`n";$tmp=$path+'.tmp-'+[Guid]::NewGuid().ToString('N');[IO.File]::WriteAllText($tmp,$json,$utf8);if(Test-Path $path){throw "Create-new target appeared: $path"};[IO.File]::Move($tmp,$path)}
Create $manifest ([ordered]@{schemaVersion=1;manifestKind='gate13r-48h-three-lane-v1-external-partial-output-manifest';createdAtUtc=[DateTime]::UtcNow.ToString('o');sourceRootRelativePath=Relative $root;fileCount=$files.Count;rawBytes=[long](($files|Measure-Object Length -Sum).Sum);files=$fileRows;pilotRootCreated=$false;formalRootCreated=$false;excludedFromReadinessAndFormalAnalysis=$true;formalCampaign=$false}) 60
Create $receipt ([ordered]@{schemaVersion=1;receiptKind='gate13r-48h-three-lane-v1-external-failure-receipt';createdAtUtc=[DateTime]::UtcNow.ToString('o');status='FAILED-NO-AUTO-RETRY-NO-RESUME / SUPERSEDED-BY-STRICT-SERIAL-DESIGN';tokens=@('NON-FORMAL','PILOT-NOT-STARTED','FORMAL-CAMPAIGN-NOT-AUTHORIZED','EXCLUDED-FROM-READINESS-AND-FORMAL-ANALYSIS','NO-AUTO-RETRY','NO-RESUME','SUPERSEDED-BY-STRICT-SERIAL-DESIGN');checkpointSha256=Hash $checkpoint;executionReceiptSha256=Hash $executionReceipt;provenanceSha256=Hash (Join-Path $ProjectPath 'Research\Gate13R_48h_10pct_3Lane_Provenance.v1.json');unityLogSha256=Hash $log;methodReadySha256=Hash $ready;blockCheckpointSha256=Hash $blockCheckpoint;partialManifestSha256=Hash $manifest;unityProcessCount=0;residualCloneLocks=$locks;pilotRootCreated=$false;formalRootCreated=$false;formalCampaign=$false}) 30
Create $diagnosis ([ordered]@{schemaVersion=1;diagnosisKind='gate13r-48h-three-lane-v1-live-log-file-share-diagnosis';createdAtUtc=[DateTime]::UtcNow.ToString('o');terminalCheckpointSha256=Hash $checkpoint;primaryFailure='The block wrapper used System.IO.File.ReadAllText while Unity retained an incompatible open handle on its live -logFile. The wrapper therefore observed an empty string and timed out despite successful serial assignment and method-ready evidence.';unityLicenseOutcome='SERIAL-ASSIGNMENT-SUCCEEDED';logFacts=@([ordered]@{lineNumber=16;classification='TRANSIENT-DIAGNOSTIC';text='Access token is unavailable; failed to update'},[ordered]@{lineNumber=21;classification='SUCCESS';text='Serial number assigned to: REDACTED'});methodReadyPresent=$true;planningWorkloadStarted=$false;secondaryFailure='The failure-evidence enumerator used the Windows PowerShell 5.1-incompatible shorthand Where-Object Name -ne<value>, so the in-root partial manifest and failure receipt were not written. Independent external evidence was written create-new instead.';requiredProspectiveRepair=@('Use a FileStream/StreamReader opened with FileShare.ReadWrite | FileShare.Delete for live Unity log inspection.','Use script-block Where-Object syntax in all failure paths.','Create a new strict-serial version; never retry, resume, overwrite, or reinterpret three-lane v1.');pilotStarted=$false;formalCampaign=$false;passedDiagnosis=$true}) 30
Write-Host 'Three-lane v1 external failure evidence sealed.' -ForegroundColor Green
